var research = @"D:\RotateRings\Research\physics_v3";
var pack = JsonUtility.FromJson<RotateRingsLevelPack>(System.IO.File.ReadAllText(System.IO.Path.Combine(research, "full500\\source_parity_pack.json")));
var catalog = JsonUtility.FromJson<RotateRingsTemplateCatalog>(System.IO.File.ReadAllText(System.IO.Path.Combine(research, "full500\\source_templates.json")));
var level = pack.levels.Find(item => item.id == 10010);
var host = new GameObject("source10010 slider2 ring1 diagnostic") { hideFlags = HideFlags.HideAndDontSave };
var lines = new System.Collections.Generic.List<string>();
try {
    var world = host.AddComponent<RotateRingsCollisionWorld>(); world.Build(level, catalog);
    var angles = new System.Collections.Generic.Dictionary<int,float>();
    foreach (var part in level.parts) angles[part.id] = part.angle;
    var removed = new System.Collections.Generic.HashSet<int> { 6, 7, 8 };
    var zeroSlides = new System.Collections.Generic.Dictionary<int,float>();
    var slides = new System.Collections.Generic.Dictionary<int,float>();
    world.ApplyState(angles, removed, zeroSlides);
    var sliderPart = level.parts.Find(part => part.id == 2);
    var sliderTemplate = System.Array.Find(catalog.templates, template => template.id == sliderPart.templateId);
    Vector2 axis = RotateRingsRules.SlideAxis(sliderPart, sliderTemplate).normalized;
    Vector2 origin = world.OwnerTransform(2).position;
    float reach = 0f;
    foreach (var part in level.parts) {
        if (removed.Contains(part.id)) continue;
        foreach (var collider in world.GetOwnerColliders(part.id)) {
            if (collider == null || !collider.enabled) continue;
            Bounds bounds = collider.bounds; Vector2 ext = bounds.extents; Vector2 center = bounds.center;
            for (int x = -1; x <= 1; x += 2) for (int y = -1; y <= 1; y += 2) {
                Vector2 corner = center + Vector2.Scale(ext, new Vector2(x, y));
                reach = Mathf.Max(reach, Mathf.Abs(Vector2.Dot(corner - origin, axis)));
            }
        }
    }
    reach += .36f;
    lines.Add("source=10010;removed=6,7,8;slider=2;axis=" + axis.x.ToString("F4", System.Globalization.CultureInfo.InvariantCulture) + "," + axis.y.ToString("F4", System.Globalization.CultureInfo.InvariantCulture) + ";reach=" + reach.ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";initialCanSolveSlider=" + world.CanSolve(2) + ";bindings=" + world.ActiveAuthoredContactCount + ";contacts=" + world.GetActiveContactSummary());
    var ringPart = level.parts.Find(part => part.id == 1);
    var ringTemplate = System.Array.Find(catalog.templates, template => template.id == ringPart.templateId);
    System.Action<string,float> attemptRing = (label, delta) => {
        world.ApplyState(angles, removed, slides);
        world.BeginGesture(1);
        float start = world.GetAngle(1); bool blocked;
        float reached = world.ClampRotation(1, start, delta, out blocked);
        int blocker = world.LastBlockerOwner; int blockerIndex = world.LastBlockerShapeIndex; string blockerRole = world.LastBlockerRole;
        world.EndGesture(1, blocked ? Mathf.Sign(delta) : 0f);
        var snapshot = (RotateRingsCollisionWorld.BindingStateSnapshot)world.CaptureBindingState();
        lines.Add(label + ";request=" + delta.ToString("F2", System.Globalization.CultureInfo.InvariantCulture) + ";reached=" + (reached-start).ToString("F2", System.Globalization.CultureInfo.InvariantCulture) + ";settled=" + world.GetAngle(1).ToString("F2", System.Globalization.CultureInfo.InvariantCulture) + ";blocked=" + blocked + ";blocker=" + blocker + ":" + blockerIndex + ":" + blockerRole + ";canSolve1=" + world.CanSolve(1) + ";bindings=" + world.ActiveAuthoredContactCount + ";active=" + string.Join(",", snapshot.activeRingRelationIndices ?? new int[0]) + ";passive=" + string.Join(",", snapshot.passiveRingRelationIndices ?? new int[0]) + ";contacts=" + world.GetActiveContactSummary());
    };
    System.Action<string,float> addGap = (label, bearing) => {
        float desired = Mathf.DeltaAngle(ringPart.angle + ringTemplate.gapDirectionDeg, bearing);
        float gap = ringTemplate.visualGap > .5f ? ringTemplate.visualGap : Mathf.Max(0f, ringPart.gap);
        float half = gap * .5f;
        foreach (float margin in new[] { 0f, -half, half, -(half + 8f), half + 8f }) {
            float delta = desired + margin;
            attemptRing(label + "-margin-" + margin.ToString("F1", System.Globalization.CultureInfo.InvariantCulture), delta);
            attemptRing(label + "-wrapped-margin-" + margin.ToString("F1", System.Globalization.CultureInfo.InvariantCulture), delta - Mathf.Sign(delta) * 360f);
        }
    };
    foreach (int sign in new[] { 1, -1 }) {
        world.ApplyState(angles, removed, zeroSlides); world.BeginGesture(2);
        float position = 0f; bool blocked = false; int guard = Mathf.CeilToInt(reach / .36f) + 5;
        lines.Add("slider2-direction=" + sign);
        for (int frame = 0; frame < guard && Mathf.Abs(position) < reach - .001f && !blocked; frame++) {
            float wanted = Mathf.Min(.36f, reach - Mathf.Abs(position));
            float before = position;
            position = world.ClampSlideForDeltaTime(2, position, position + sign * wanted, 1f / 60f, out blocked);
            int blocker = world.LastBlockerOwner; int blockerIndex = world.LastBlockerShapeIndex; string blockerRole = world.LastBlockerRole;
            lines.Add("slider2-frame=" + frame + ";from=" + before.ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";to=" + position.ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";blocked=" + blocked + ";blocker=" + blocker + ":" + blockerIndex + ":" + blockerRole);
            if (Mathf.Abs(position-before) < 1e-6f) break;
        }
        world.EndGesture(2);
        slides.Clear(); slides[2] = world.GetSlide(2);
        var moved = (RotateRingsCollisionWorld.BindingStateSnapshot)world.CaptureBindingState();
        lines.Add("slider2-terminal;direction=" + sign + ";slide=" + world.GetSlide(2).ToString("F3", System.Globalization.CultureInfo.InvariantCulture) + ";blocked=" + blocked + ";canSolve=" + world.CanSolve(2) + ";bindings=" + world.ActiveAuthoredContactCount + ";active=" + string.Join(",", moved.activeRingRelationIndices ?? new int[0]) + ";passive=" + string.Join(",", moved.passiveRingRelationIndices ?? new int[0]) + ";contacts=" + world.GetActiveContactSummary());
        Vector2 ringCenter = world.OwnerTransform(1).position;
        float axisBearing = Mathf.Atan2(axis.y, axis.x) * Mathf.Rad2Deg;
        addGap("ring1-slider2-axis-plus-dir-" + sign, axisBearing);
        addGap("ring1-slider2-axis-minus-dir-" + sign, axisBearing + 180f);
        for (int shapeIndex = 0; shapeIndex < world.GetOwnerShapeCount(2); shapeIndex++) {
            if (world.GetOwnerShapeRole(2, shapeIndex) != "body" || !world.TryGetShapeWorldCenter(2, shapeIndex, out var center)) continue;
            Vector2 toCenter = center - ringCenter;
            if (toCenter.sqrMagnitude > 1e-8f) addGap("ring1-slider2-body-center-dir-" + sign, Mathf.Atan2(toCenter.y, toCenter.x) * Mathf.Rad2Deg);
        }
        foreach (var contact in world.GetActiveAuthoredContacts()) {
            if (contact.kind != "ring-link" || contact.ownerId != 9 || contact.targetId != 1 || contact.ownerRole != "head_trigger" || contact.targetRole != "body") continue;
            if (!world.TryGetShapeWorldCenter(contact.ownerId, contact.ownerShapeIndex, out var sourceCenter)) continue;
            Vector2 sourceVector = sourceCenter - ringCenter;
            if (sourceVector.sqrMagnitude > 1e-8f) addGap("ring1-source9-bearing-" + contact.ownerShapeIndex + "-dir-" + sign, Mathf.Atan2(sourceVector.y, sourceVector.x) * Mathf.Rad2Deg);
        }
    }
    var destination = System.IO.Path.Combine(research, "source10010_slider2_ring1_diagnostic.txt");
    System.IO.File.WriteAllLines(destination, lines);
    return destination + " rows=" + lines.Count;
}
finally { UnityEngine.Object.DestroyImmediate(host); }
